async function api(path,options={}){const headers={...(options.headers||{})};if(state.csrf&&options.method&&options.method!=='GET')headers['X-CSRF-Token']=state.csrf;const response=await fetch(path,{...options,headers});if(response.status===204)return null;const raw=await response.text();let body={};try{body=raw?JSON.parse(raw):{}}catch{}if(!response.ok){const detail=body.error||'Request failed';throw new Error(`${detail} (HTTP ${response.status}, ${path})`)}return body}
