$('#auth-form').addEventListener('submit',async(event)=>{event.preventDefault();const submittedForm=event.currentTarget;$('#auth-error').textContent='';try{const remember=submittedForm.dataset.setup!=='1'&&$('#remember-login').checked;const payload={username:$('#username').value,password:$('#password').value,bootstrap_token:$('#bootstrap-token').value,remember_me:remember};await api(submittedForm.dataset.setup==='1'?'/api/setup/admin':'/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(submittedForm.dataset.setup!=='1'){localStorage.setItem('studio-remember-login',remember?'1':'0');if(remember)localStorage.setItem('studio-remembered-username',$('#username').value.trim());else localStorage.removeItem('studio-remembered-username')}const me=await api('/api/me');state.user=me.user;state.csrf=me.csrf;$('#password').value='';await enterStudio()}catch(error){$('#auth-error').textContent=error.message}});
async function pollAppVersion(){clearTimeout(state.versionTimer);try{const response=await fetch(`/?version_check=${Date.now()}`,{cache:'no-store'});const html=await response.text();const match=html.match(/app\.js\?v=(\d+)/);if(match&&match[1]!==APP_VERSION){return}}catch(error){console.warn('Version check unavailable',error)}finally{if(state.user)state.versionTimer=setTimeout(pollAppVersion,30000)}}async function pollPresence(){clearTimeout(state.presenceTimer);if(!state.user||state.user.role!=='admin')return;try{const data=await api('/api/projects');const onlineByOwner=new Map(data.projects.map(project=>[String(project.owner_id),Boolean(project.owner_online)]));for(const group of $$('.project-owner-group[data-owner-id]')){const online=onlineByOwner.get(String(group.dataset.ownerId))===true;const dot=group.querySelector('.user-presence-dot');if(dot){dot.classList.toggle('online',online);dot.title=online?'Online now':'Offline'}}}catch(error){console.warn('Presence unavailable',error)}finally{if(state.user&&state.user.role==='admin')state.presenceTimer=setTimeout(pollPresence,15000)}}
