function prepareAssetUpscale(asset){if(!asset||!['image','video'].includes(asset.kind))return;if(!state.project||state.project.can_edit===false)return alert('This project is view-only.');const upscaleMode=$('.mode[data-mode="upscale"]');if(!upscaleMode)return alert('Upscale is not available.');upscaleMode.click();const item={assetId:asset.id,filename:asset.filename,mime_type:asset.mime_type,url:asset.url};state.sourceMedia=item;$('#source-media-mark').textContent='✓';renderSingleReferencePreview('#source-media-mark',item);selectDefaultUpscaler(asset.kind);if($('#asset-dialog').open)$('#asset-dialog').close();const sourceCard=$('#source-media').closest('.upload-card');sourceCard.classList.remove('source-ready');requestAnimationFrame(()=>sourceCard.classList.add('source-ready'));setTimeout(()=>sourceCard.classList.remove('source-ready'),1400);closeMobileSidebar()}
