const CINEMA_MOVEMENT_INSTRUCTIONS={'Static':'locked-off static tripod camera within each individual shot; no camera movement; only natural subject motion; identity, wardrobe, lighting and environment remain consistent','Push in':'one continuous slow, smooth, steady camera push-in toward the main subject within each individual shot, no zoom, no camera shake; subject identity, lighting and composition remain consistent','Pull back':'one continuous slow, smooth, steady physical camera pull-back away from the main subject within each individual shot, gradually revealing the environment, no zoom, no camera shake; subject identity and lighting remain consistent','Pan left':'one continuous slow, smooth physical camera pan to the left within each individual shot, rotating horizontally from right to left and revealing the environment on the left, no dolly, no zoom, no camera shake; subject identity and lighting remain consistent','Pan right':'one continuous slow, smooth physical camera pan to the right within each individual shot, rotating horizontally from left to right and revealing the environment on the right, no dolly, no zoom, no camera shake; subject identity and lighting remain consistent','Tilt up':'one continuous slow, smooth physical camera tilt upward within each individual shot, rotating vertically from low framing toward the subject and environment above; fixed camera position, no pan, no dolly, no zoom, no camera shake; identity and lighting remain consistent','Tilt down':'one continuous slow, smooth physical camera tilt downward within each individual shot, rotating vertically from upper framing toward the subject and environment below; fixed camera position, no pan, no dolly, no zoom, no camera shake; identity and lighting remain consistent','Dolly':'one continuous smooth lateral dolly move past the subject with clear foreground and background parallax; physical camera translation, no pan, no zoom; identity and lighting remain consistent','Dolly zoom':'one continuous cinematic dolly zoom, also called the Vertigo effect: the main subject remains stationary, centered and the same apparent size while the camera physically dollies backward away from the subject and the lens smoothly zooms in at a precisely synchronized rate; the distant background appears to rush closer and compress while nearby foreground space stretches and moves away; strong changing perspective with no subject scale drift, no pan and no camera shake; preserve subject identity, pose, wardrobe and lighting','Truck':'one continuous smooth truck movement alongside the moving subject at constant distance with lateral parallax; no pan, no zoom; identity and lighting remain consistent','Orbit':'one continuous slow smooth camera orbit around the subject while keeping the subject centered with natural parallax, no zoom; identity and lighting remain consistent','Crane':'one continuous smooth crane movement rising vertically from a lower viewpoint to a high-angle view while revealing the environment, no zoom; identity and lighting remain consistent','Handheld':'controlled realistic handheld camera with subtle human micro-movement and gentle breathing sway; no abrupt shake; identity and lighting remain consistent','Tracking shot':'one continuous smooth tracking shot following the moving subject at constant distance with stable composition and natural parallax, no zoom; identity and lighting remain consistent'};
function cinemaCameraInstruction(value){return CINEMA_MOVEMENT_INSTRUCTIONS[value]||value}
function movementCard(value,label){const button=document.createElement('button');button.type='button';const preview=CINEMA_MOVEMENT_PREVIEWS[value];const enabled=Boolean(preview);button.className=`cinema-movement-card${$('#cinema-camera').value===value?' selected':''}${enabled?'':' upcoming'}`;button.disabled=!enabled;button.setAttribute('aria-disabled',String(!enabled));button.innerHTML=preview?(value===""?`<span class="movement-demo auto-color-demo" aria-hidden="true"></span><b>${label}</b><small>Model decides automatically</small>`:`<span class="movement-demo video-demo"><video src="${preview}" autoplay muted loop playsinline preload="metadata"></video></span><b>${label}</b><small>MiniMax H3 · Functional</small>`):`<span class="movement-demo upcoming-demo"><strong>COMING SOON</strong></span><b>${label}</b><small>Upcoming</small>`;if(enabled)button.onclick=()=>{setCinemaControl('#cinema-camera',value);renderCinemaPicker()};return button}
function pickerTabs(names){const nav=document.createElement('nav');nav.className='cinema-picker-tabs';for(const name of names){const button=document.createElement('button');button.type='button';button.classList.toggle('active',cinemaPickerTab===name);button.textContent=name;button.onclick=()=>{cinemaPickerTab=name;renderCinemaPicker()};nav.append(button)}return nav}
function renderCinemaPicker(){const body=$('#cinema-picker-body');body.innerHTML='';$('#cinema-picker-title').textContent={film:'Film setup',camera:'Camera',palette:'Color palette',lighting:'Lighting',shots:'Shot plan'}[cinemaPickerType];$('#cinema-picker-custom').hidden=cinemaPickerType==='camera'||cinemaPickerType==='shots';if(cinemaPickerType==='film'){if(!CINEMA_VISUALS.film[cinemaPickerTab])cinemaPickerTab='Genre';body.append(pickerTabs(['Genre','Era','Pacing','Tempo']));const grid=document.createElement('div');grid.className='cinema-visual-grid';const field={Genre:'#cinema-genre',Era:'#cinema-era',Pacing:'#cinema-pacing',Tempo:'#cinema-tempo'}[cinemaPickerTab];for(const option of CINEMA_VISUALS.film[cinemaPickerTab])grid.append(cinemaPickerTab==='Genre'?genreCard(option[0],option[1]):cinemaPickerTab==='Era'?eraCard(option[0],option[1]):cinemaPickerTab==='Pacing'?pacingCard(option[0],option[1]):tempoCard(option[0],option[1]));body.append(grid)}else if(cinemaPickerType==='camera'){if(!['Movement','Lens'].includes(cinemaPickerTab))cinemaPickerTab='Movement';body.append(pickerTabs(['Movement','Lens']));const grid=document.createElement('div');grid.className=cinemaPickerTab==='Movement'?'cinema-movement-grid':'cinema-visual-grid';for(const option of CINEMA_VISUALS.camera[cinemaPickerTab])grid.append(cinemaPickerTab==='Movement'?movementCard(...option):lensCard(option[0],option[1]));body.append(grid)}else if(cinemaPickerType==='palette'){const grid=document.createElement('div');grid.className='cinema-visual-grid';for(const option of CINEMA_VISUALS.palette)grid.append(visualCard(...option,'#cinema-palette'));body.append(grid)}else if(cinemaPickerType==='lighting'){const grid=document.createElement('div');grid.className='cinema-visual-grid';for(const option of CINEMA_VISUALS.lighting)grid.append(lightingCard(option[0],option[1]));body.append(grid)}else{const modes=document.createElement('div');modes.className='cinema-modal-modes';for(const [value,label,help]of[['single','Single shot','One continuous camera shot'],['auto','Auto multishot','Model decides all shots and cuts automatically'],['custom','Custom multishot','Manually build one continuous video with camera cuts']]){const button=document.createElement('button');button.type='button';button.classList.toggle('selected',cinema.mode===value);button.innerHTML=`<b>${label}</b><small>${help}</small>`;button.onclick=()=>{$(`[data-cinema-mode="${value}"]`).click();renderCinemaPicker();updateCinemaDock()};modes.append(button)}body.append(modes);const guides={single:{title:'Create one uninterrupted shot',steps:['Write the complete scene and action in the main prompt below.','Choose camera movement and lens from Camera if needed.','Set Model, Ratio, Resolution and total Duration in the composer, then Generate.'],note:'The entire video will be one continuous take with no editorial cuts.'},auto:{title:'Let the model direct every cut automatically',steps:['Write the complete scene once in the main prompt.','Set the total Duration in the composer.','Generate — the model decides shot count, framing, camera movement, order and cut timing.'],note:'No manual shot boxes or editable timeline are needed in Auto multishot.'},custom:{title:'Build every camera cut manually',steps:['Set the total Duration in the composer below; it appears above the shot timeline.','Enter the duration for each shot above its prompt. The next shot starts exactly where the previous one ends.','Use the live Planned and Remaining counters, then describe each shot and camera framing.'],note:'All shot ranges must fit the global duration and remain one coherent video.'}};const guide=guides[cinema.mode];const help=document.createElement('div');help.className=`cinema-multishot-help mode-${cinema.mode}`;help.innerHTML=`<b>${guide.title}</b><ol>${guide.steps.map(step=>`<li>${step}</li>`).join('')}</ol><span>${guide.note}</span>`;body.append(help);if(cinema.mode==='custom'){const tools=document.createElement('div');tools.className='cinema-modal-shot-tools';tools.innerHTML='<button type="button" data-add>Add another shot</button>';tools.querySelector('[data-add]').onclick=()=>{cinema.shots.push(cinemaShot());renderCinemaShots();renderCinemaPicker()};body.append(tools);const modalList=document.createElement('div');modalList.className='cinema-shot-list';body.append(modalList);renderCinemaShots(modalList)}}}
