function updateCinemaDock(){const film=[$('#cinema-era').value,$('#cinema-genre').value,$('#cinema-pacing').value,$('#cinema-tempo').value].filter(Boolean).join(', ')||'Auto';$('#cinema-film-summary').textContent=film;$('#cinema-camera-summary').textContent=[$('#cinema-camera').value,$('#cinema-lens').value].filter(Boolean).join(', ')||'Auto';$('#cinema-palette-summary').textContent=$('#cinema-palette').value||'Auto';$('#cinema-lighting-summary').textContent=$('#cinema-lighting').value||'Auto';$('#cinema-shots-summary').textContent=cinema.mode==='single'?'Single':cinema.mode==='auto'?'Auto multishot':`${cinema.shots.length} custom shots`}
