const customPalette={open:false,colors:['#173F5F','#D99A3D','#3A8D88'],active:0,hue:210,intensity:65};
function paletteStorageKey(){return`cinema-color-palettes:${state.user?.id||'guest'}`}
function paletteFavoritesKey(){return`cinema-palette-favorites:${state.user?.id||'guest'}`}
function favoritePaletteNames(){try{const names=JSON.parse(localStorage.getItem(paletteFavoritesKey())||'[]');return Array.isArray(names)?names:[]}catch{return[]}}
function togglePaletteFavorite(label){const names=favoritePaletteNames(),index=names.indexOf(label);if(index>=0)names.splice(index,1);else names.push(label);localStorage.setItem(paletteFavoritesKey(),JSON.stringify(names));hidePaletteHoverPreview();renderPalettePicker()}
function savedColorPalettes(){try{return JSON.parse(localStorage.getItem(paletteStorageKey())||'[]')}catch{return[]}}
function hexRgb(hex){const value=String(hex).replace('#','').padEnd(6,'0').slice(0,6);return[0,2,4].map(index=>parseInt(value.slice(index,index+2),16)||0)}
function rgbHex(r,g,b){return'#'+[r,g,b].map(value=>Math.max(0,Math.min(255,Math.round(value))).toString(16).padStart(2,'0')).join('').toUpperCase()}
function hsvHex(h,s,v){const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c;let rgb=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return rgbHex(...rgb.map(n=>(n+m)*255))}
function hexHue(hex){const[r,g,b]=hexRgb(hex).map(n=>n/255),max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;if(!d)return 0;let h=max===r?60*((g-b)/d%6):max===g?60*((b-r)/d+2):60*((r-g)/d+4);return(h+360)%360}
function customPalettePrompt(){const roles=['dominant','secondary','accent'];const colors=customPalette.colors.map((color,index)=>`${roles[index]||`accent ${index-1}`} ${color}`).join(', ');return`custom cinematic color palette: ${colors}; palette influence ${customPalette.intensity} percent; apply colors through production design, wardrobe, environment, lighting, shadows and highlights; preserve realistic skin tones and neutral whites; maintain natural contrast; avoid a flat uniform color overlay`}
function setCustomPreview(){const preview=$('.custom-palette-preview');if(!preview)return;const gradient=`linear-gradient(125deg,${customPalette.colors.join(',')})`;preview.style.setProperty('--palette-gradient',gradient);preview.style.setProperty('--palette-opacity',String(customPalette.intensity/100));const hex=$('#custom-palette-hex');if(hex)hex.value=customPalette.colors[customPalette.active];const range=$('#custom-palette-intensity');if(range)range.value=customPalette.intensity;const value=$('#custom-palette-intensity-value');if(value)value.textContent=`${customPalette.intensity}%`;for(const[slot,button]of [...document.querySelectorAll('[data-palette-slot]')].entries()){button.classList.toggle('active',slot===customPalette.active);button.style.setProperty('--swatch',customPalette.colors[slot])}}
function paletteGridPoint(event,commit=false){const grid=$('#custom-color-grid');if(!grid)return;const rect=grid.getBoundingClientRect(),x=Math.max(0,Math.min(rect.width,event.clientX-rect.left)),y=Math.max(0,Math.min(rect.height,event.clientY-rect.top));const saturation=x/rect.width,value=1-y/rect.height;customPalette.colors[customPalette.active]=hsvHex(customPalette.hue,saturation,value);const cursor=grid.querySelector('i');cursor.style.left=`${x}px`;cursor.style.top=`${y}px`;setCustomPreview();if(commit)grid.dataset.committed=customPalette.colors[customPalette.active]}
function renderCustomPaletteEditor(){customPalette.open=true;$('#cinema-picker-title').textContent='Custom color palette';$('#cinema-picker-help').textContent='Move across the grid for live preview. Release to select; Apply uses it in this generation.';$('#cinema-picker-custom').hidden=false;$('#cinema-picker-custom').textContent='Save palette';$('#cinema-picker-done').textContent='Apply';const body=$('#cinema-picker-body');body.innerHTML=`<section class="custom-palette-editor"><div class="custom-palette-preview"><img src="/assets/cinema/lens/50mm.jpg" alt="Custom palette preview"><span></span></div><div class="custom-palette-controls"><div class="custom-palette-swatches"></div><button type="button" id="custom-palette-add">＋ Add color</button><button type="button" id="custom-palette-remove">− Remove</button><label>Color grid<div id="custom-color-grid" tabindex="0"><i></i></div></label><label>Hue<input id="custom-palette-hue" type="range" min="0" max="359" value="${customPalette.hue}"></label><label>HEX<input id="custom-palette-hex" maxlength="7" value="${customPalette.colors[customPalette.active]}"></label><label>Palette influence <b id="custom-palette-intensity-value">${customPalette.intensity}%</b><input id="custom-palette-intensity" type="range" min="10" max="100" value="${customPalette.intensity}"></label><p>Final model instruction preserves natural skin tones and avoids a flat color wash.</p></div></section>`;const swatches=body.querySelector('.custom-palette-swatches');customPalette.colors.forEach((color,index)=>{const button=document.createElement('button');button.type='button';button.dataset.paletteSlot=String(index);button.innerHTML=`<i></i><span>${['Dominant','Secondary','Accent'][index]||`Accent ${index-1}`}</span>`;button.onclick=()=>{customPalette.active=index;customPalette.hue=hexHue(customPalette.colors[index]);$('#custom-palette-hue').value=customPalette.hue;setCustomPreview()};swatches.append(button)});const grid=$('#custom-color-grid');grid.style.setProperty('--hue',customPalette.hue);let dragging=false;grid.onpointerdown=event=>{dragging=true;grid.setPointerCapture(event.pointerId);paletteGridPoint(event)};grid.onpointermove=event=>{if(dragging)paletteGridPoint(event)};grid.onpointerup=event=>{dragging=false;paletteGridPoint(event,true)};$('#custom-palette-hue').oninput=event=>{customPalette.hue=Number(event.target.value);grid.style.setProperty('--hue',customPalette.hue)};$('#custom-palette-hex').onchange=event=>{if(/^#[0-9a-f]{6}$/i.test(event.target.value)){customPalette.colors[customPalette.active]=event.target.value.toUpperCase();customPalette.hue=hexHue(event.target.value);$('#custom-palette-hue').value=customPalette.hue;grid.style.setProperty('--hue',customPalette.hue);setCustomPreview()}else event.target.value=customPalette.colors[customPalette.active]};$('#custom-palette-intensity').oninput=event=>{customPalette.intensity=Number(event.target.value);setCustomPreview()};$('#custom-palette-add').onclick=()=>{if(customPalette.colors.length>=5)return;customPalette.colors.push('#FFFFFF');customPalette.active=customPalette.colors.length-1;renderCustomPaletteEditor()};$('#custom-palette-remove').onclick=()=>{if(customPalette.colors.length<=1)return;customPalette.colors.splice(customPalette.active,1);customPalette.active=Math.min(customPalette.active,customPalette.colors.length-1);renderCustomPaletteEditor()};setCustomPreview()}
function savedPaletteCard(item,index){const visual=`linear-gradient(90deg,${item.colors.join(',')})`;const card=visualCard(item.prompt,item.name,visual,'#cinema-palette');const remove=document.createElement('button');remove.type='button';remove.className='palette-delete';remove.textContent='×';remove.title='Delete saved palette';remove.onclick=event=>{event.stopPropagation();const items=savedColorPalettes();items.splice(index,1);localStorage.setItem(paletteStorageKey(),JSON.stringify(items));renderCinemaPicker()};card.append(remove);return card}
function renderPalettePicker(){customPalette.open=false;$('#cinema-picker-title').textContent='Color palette';$('#cinema-picker-help').textContent='Choose a functional palette, save favorites, or build a custom one.';$('#cinema-picker-custom').hidden=true;$('#cinema-picker-done').textContent='Done';const body=$('#cinema-picker-body');body.innerHTML='';const options=CINEMA_VISUALS.palette;const top=document.createElement('div');top.className='cinema-visual-grid palette-primary-grid';top.append(visualCard(...options[0],'#cinema-palette'));const custom=document.createElement('button');custom.type='button';custom.className='cinema-visual-card custom-palette-launch';custom.innerHTML='<span class="cinema-visual-thumb auto-color-demo"></span><b>Custom palette</b><small>Choose exact colors</small>';custom.onclick=renderCustomPaletteEditor;top.append(custom);body.append(top);const favorites=favoritePaletteNames();if(favorites.length){const title=document.createElement('h3');title.className='palette-section-title';title.textContent='★ Favorites';const favoriteGrid=document.createElement('div');favoriteGrid.className='cinema-visual-grid palette-favorites-grid';for(const option of options.slice(1))if(favorites.includes(option[1]))favoriteGrid.append(visualCard(...option,'#cinema-palette'));body.append(title,favoriteGrid)}const allTitle=document.createElement('h3');allTitle.className='palette-section-title';allTitle.textContent='All palettes';const grid=document.createElement('div');grid.className='cinema-visual-grid';for(const option of options.slice(1))grid.append(visualCard(...option,'#cinema-palette'));savedColorPalettes().forEach((item,index)=>grid.append(savedPaletteCard(item,index)));body.append(allTitle,grid)}
const customLighting={open:false,active:0,draft:null,applied:null};
const LIGHTING_ANCHORS={Top:{azimuth:0,elevation:90},Front:{azimuth:0,elevation:0},Right:{azimuth:90,elevation:0},Left:{azimuth:-90,elevation:0},Back:{azimuth:180,elevation:0},Bottom:{azimuth:0,elevation:-90}};
function normalizeAngle(value){let angle=Number(value)||0;while(angle>180)angle-=360;while(angle<=-180)angle+=360;return angle}
function ensureLightOrbit(light){const anchor=LIGHTING_ANCHORS[light.position]||LIGHTING_ANCHORS.Front;if(!Number.isFinite(Number(light.azimuth)))light.azimuth=anchor.azimuth;if(!Number.isFinite(Number(light.elevation)))light.elevation=anchor.elevation;light.azimuth=normalizeAngle(light.azimuth);light.elevation=Math.max(-90,Math.min(90,Number(light.elevation)||0));return light}
function defaultCustomLight(index=0){return ensureLightOrbit({name:'Light '+(index+1),type:index===0?'Key light':'Fill light',color:index===0?'#FFFFFF':'#7FA8FF',brightness:index===0?60:35,diffusion:index===0?50:75,position:index===0?'Front':'Right'})}
function setLightAnchor(light,position){const anchor=LIGHTING_ANCHORS[position]||LIGHTING_ANCHORS.Front;light.position=position;light.azimuth=anchor.azimuth;light.elevation=anchor.elevation;return light}
function lightVector(light){ensureLightOrbit(light);const azimuth=light.azimuth*Math.PI/180,elevation=light.elevation*Math.PI/180,cosElevation=Math.cos(elevation);return{x:Math.sin(azimuth)*cosElevation,y:-Math.sin(elevation),z:Math.cos(azimuth)*cosElevation}}
function ensureSubjectOrbit(preset){if(!Number.isFinite(Number(preset.subjectYaw)))preset.subjectYaw=0;if(!Number.isFinite(Number(preset.subjectPitch)))preset.subjectPitch=0;preset.subjectYaw=normalizeAngle(preset.subjectYaw);preset.subjectPitch=Math.max(-35,Math.min(35,Number(preset.subjectPitch)||0));return preset}
function subjectFacingLabel(preset){ensureSubjectOrbit(preset);const yaw=Math.abs(preset.subjectYaw);if(yaw<=25)return'facing front';if(yaw>=155)return'facing back';return preset.subjectYaw>0?'turned toward camera-right':'turned toward camera-left'}
function relativeLightVector(light,preset){ensureLightOrbit(light);ensureSubjectOrbit(preset);const azimuth=normalizeAngle(light.azimuth-preset.subjectYaw)*Math.PI/180,elevation=Math.max(-90,Math.min(90,light.elevation-preset.subjectPitch))*Math.PI/180,cosElevation=Math.cos(elevation);return{x:Math.sin(azimuth)*cosElevation,y:-Math.sin(elevation),z:Math.cos(azimuth)*cosElevation}}
function lightDirectionLabel(light,preset=customLighting.draft||{subjectYaw:0,subjectPitch:0}){const{x,y,z}=relativeLightVector(light,preset);const vertical=y<-.55?'high ':y>.55?'low ':'';const side=x<-.3?'subject-right ':x>.3?'subject-left ':'';const depth=z<-.35?'from behind the subject':z>.35?'from the subject front':'from the subject side';return(vertical+side+depth).trim()}
function positionLightBeam(beam,light,x,y,z){if(!beam)return;const dx=x*43,dy=y*43,length=Math.hypot(dx,dy),angle=Math.atan2(dy,dx)*180/Math.PI;beam.style.width=`${length}%`;beam.style.transform=`translateY(-50%) rotate(${angle}deg)`;beam.style.setProperty('--light-color',light.color);beam.style.opacity=String(.22+(z+1)*.17);beam.style.zIndex=z<0?'7':'20';beam.classList.toggle('behind',z<0)}
function positionLightDot(dot,light){const{x,y,z}=lightVector(light);const scale=.82+(z+1)*.13;dot.style.left=`calc(${50+x*43}% - 13px)`;dot.style.top=`calc(${50+y*43}% - 13px)`;dot.style.transform=`scale(${scale.toFixed(3)})`;dot.style.opacity=String(.72+(z+1)*.14);dot.style.zIndex=z<0?'8':'25';dot.classList.toggle('behind',z<0);dot.title=lightDirectionLabel(light);dot.setAttribute('aria-label',`${light.name}: ${dot.title}. Drag to reposition.`);positionLightBeam(dot._beam,light,x,y,z)}
function positionLightingSubject(subject,preset){ensureSubjectOrbit(preset);subject.style.transform=`perspective(520px) rotateX(${-preset.subjectPitch}deg) rotateY(${preset.subjectYaw}deg)`;subject.dataset.facing=Math.abs(preset.subjectYaw)>=155?'back':Math.abs(preset.subjectYaw)>25?'side':'front';subject.title=`Subject ${subjectFacingLabel(preset)}. Drag to rotate.`;subject.setAttribute('aria-label',subject.title)}
function bindLightingSubject(subject,preset){let drag=null,frame=0,pending=null;const paint=()=>{frame=0;if(!drag||!pending)return;preset.subjectYaw=normalizeAngle(drag.yaw+(pending.x-drag.x)*.7);preset.subjectPitch=Math.max(-35,Math.min(35,drag.pitch-(pending.y-drag.y)*.35));positionLightingSubject(subject,preset);updateCustomLightingLabels();pending=null};subject.onpointerdown=event=>{event.preventDefault();event.stopPropagation();ensureSubjectOrbit(preset);subject.setPointerCapture(event.pointerId);drag={x:event.clientX,y:event.clientY,yaw:preset.subjectYaw,pitch:preset.subjectPitch};subject.classList.add('dragging')};subject.onpointermove=event=>{if(!drag||!subject.hasPointerCapture(event.pointerId))return;pending={x:event.clientX,y:event.clientY};if(!frame)frame=requestAnimationFrame(paint)};const finish=event=>{if(!drag)return;if(frame){cancelAnimationFrame(frame);frame=0}if(pending)paint();if(subject.hasPointerCapture(event.pointerId))subject.releasePointerCapture(event.pointerId);drag=null;pending=null;subject.classList.remove('dragging');renderCustomLightingEditor()};subject.onpointerup=finish;subject.onpointercancel=finish}
function nearestLightAnchor(light){ensureLightOrbit(light);let nearest='',distance=Infinity;for(const[position,anchor]of Object.entries(LIGHTING_ANCHORS)){const azimuthDelta=Math.abs(normalizeAngle(light.azimuth-anchor.azimuth)),elevationDelta=Math.abs(light.elevation-anchor.elevation),score=azimuthDelta+elevationDelta;if(score<distance){nearest=position;distance=score}}return distance<3?nearest:''}
function bindLightDotDrag(dot,light,index){let drag=null,frame=0,pending=null;const paint=()=>{frame=0;if(!drag||!pending)return;light.azimuth=normalizeAngle(drag.azimuth+(pending.x-drag.x)*.75);light.elevation=Math.max(-90,Math.min(90,drag.elevation-(pending.y-drag.y)*.75));light.position=nearestLightAnchor(light)||'Custom';positionLightDot(dot,light);updateCustomLightingLabels();pending=null};dot.onpointerdown=event=>{event.preventDefault();event.stopPropagation();customLighting.active=index;for(const item of $$('.lighting-orbit-dot'))item.classList.toggle('active',item===dot);dot.setPointerCapture(event.pointerId);drag={x:event.clientX,y:event.clientY,azimuth:ensureLightOrbit(light).azimuth,elevation:light.elevation};dot.classList.add('dragging')};dot.onpointermove=event=>{if(!drag||!dot.hasPointerCapture(event.pointerId))return;pending={x:event.clientX,y:event.clientY};if(!frame)frame=requestAnimationFrame(paint)};const finish=event=>{if(!drag)return;if(frame){cancelAnimationFrame(frame);frame=0}if(pending)paint();if(dot.hasPointerCapture(event.pointerId))dot.releasePointerCapture(event.pointerId);drag=null;pending=null;dot.classList.remove('dragging');renderCustomLightingEditor()};dot.onpointerup=finish;dot.onpointercancel=finish}
function lightingPresetsKey(){return'cinema-lighting-presets:'+(state.user?.id||'guest')}
function savedLightingPresets(){try{const rows=JSON.parse(localStorage.getItem(lightingPresetsKey())||'[]');return Array.isArray(rows)?rows:[]}catch{return[]}}
function saveLightingPresets(rows){localStorage.setItem(lightingPresetsKey(),JSON.stringify(rows))}
function cloneLighting(value){return JSON.parse(JSON.stringify(value))}
function lightingIntensity(value){return value<=25?'subtle':value<=50?'moderate':value<=75?'strong':'very intense'}
function lightingSoftness(value){return value<=20?'hard and directional with defined shadows':value<=45?'moderately hard with controlled shadows':value<=75?'soft and diffused with gentle shadows':'very soft and broadly wrapped with minimal hard shadows'}
function customLightingPromptFor(preset){const lights=(preset?.lights||[]).slice(0,3);if(!lights.length)return'';ensureSubjectOrbit(preset);const parts=lights.map((light,index)=>{ensureLightOrbit(light);return'Light '+(index+1)+' ('+(light.type||'cinematic light')+'): '+lightingIntensity(Number(light.brightness)||0)+' '+String(light.color||'#FFFFFF').toUpperCase()+' light '+lightDirectionLabel(light,preset)+' (world azimuth '+Math.round(light.azimuth)+' degrees, elevation '+Math.round(light.elevation)+' degrees), '+lightingSoftness(Number(light.diffusion)||0)});return'custom cinematic lighting rig; subject '+subjectFacingLabel(preset)+' (yaw '+Math.round(preset.subjectYaw)+' degrees, pitch '+Math.round(preset.subjectPitch)+' degrees); '+parts.join('; ')+'; balance exposure across all lights, preserve believable shadow direction, natural skin tones, highlight detail and cinematic contrast'}
function customLightingInstruction(value){if(!String(value).startsWith('custom-light:'))return'';const id=String(value).slice(13);const preset=id==='draft'?customLighting.applied:savedLightingPresets().find(item=>item.id===id);return customLightingPromptFor(preset)}
function ensureLightingOption(value,label){const select=$('#cinema-lighting');let option=[...select.options].find(item=>item.value===value);if(!option){option=new Option(label,value);select.add(option)}else option.textContent=label}
function setCustomLightingSelection(preset,id='draft'){const value='custom-light:'+id;ensureLightingOption(value,preset.name||'Custom lighting');if(id==='draft')customLighting.applied=cloneLighting(preset);setCinemaControl('#cinema-lighting',value);updateCinemaDock()}
function newLightingPreset(){customLighting.draft={name:'My lighting preset',subjectYaw:0,subjectPitch:0,lights:[defaultCustomLight(0)]};customLighting.active=0;customLighting.open=true;renderCustomLightingEditor()}
function customLightingLaunchCard(){const button=document.createElement('button');button.type='button';button.className='cinema-visual-card new-lighting-card';button.innerHTML='<span class="cinema-visual-thumb new-lighting-demo"><i>+</i><em></em></span><b>New lighting preset</b><small>Place and shape up to 3 lights</small>';button.onclick=newLightingPreset;return button}
function savedLightingCard(preset){const value='custom-light:'+preset.id;ensureLightingOption(value,preset.name);const button=document.createElement('button');button.type='button';button.className='cinema-visual-card saved-lighting-card'+($('#cinema-lighting').value===value?' selected':'');const preview=document.createElement('span');preview.className='cinema-visual-thumb saved-lighting-demo';for(const light of preset.lights.slice(0,3)){const dot=document.createElement('i');dot.style.setProperty('--light-color',light.color);dot.dataset.position=light.position;preview.append(dot)}const title=document.createElement('b');title.textContent=preset.name;const detail=document.createElement('small');detail.textContent=preset.lights.length+' light'+(preset.lights.length===1?'':'s')+' - Functional';const actions=document.createElement('span');actions.className='saved-lighting-actions';const edit=document.createElement('button');edit.type='button';edit.textContent='Edit';edit.onclick=event=>{event.stopPropagation();customLighting.draft=cloneLighting(preset);customLighting.active=0;customLighting.open=true;renderCustomLightingEditor()};const remove=document.createElement('button');remove.type='button';remove.textContent='Delete';remove.onclick=event=>{event.stopPropagation();const rows=savedLightingPresets().filter(item=>item.id!==preset.id);saveLightingPresets(rows);if($('#cinema-lighting').value===value)setCinemaControl('#cinema-lighting','');renderLightingPicker()};actions.append(edit,remove);button.append(preview,title,detail,actions);button.onclick=()=>{setCustomLightingSelection(preset,preset.id);renderLightingPicker()};return button}
function renderLightingPicker(){customLighting.open=false;$('#cinema-picker-title').textContent='Lighting';$('#cinema-picker-help').textContent='Choose a functional preset or build and save your own lighting rig.';$('#cinema-picker-custom').hidden=true;$('#cinema-picker-done').textContent='Done';const body=$('#cinema-picker-body');body.innerHTML='';const grid=document.createElement('div');grid.className='cinema-visual-grid lighting-picker-grid';grid.append(customLightingLaunchCard());for(const option of CINEMA_VISUALS.lighting)grid.append(lightingCard(option[0],option[1]));for(const preset of savedLightingPresets())grid.append(savedLightingCard(preset));body.append(grid)}
function updateCustomLightingLabels(){const preset=customLighting.draft,light=preset?.lights[customLighting.active];if(!light)return;ensureLightOrbit(light);ensureSubjectOrbit(preset);const brightness=$('#custom-light-brightness-value');if(brightness)brightness.textContent=light.brightness+'%';const diffusion=$('#custom-light-diffusion-value');if(diffusion)diffusion.textContent=light.diffusion+'%';const direction=$('#custom-light-direction');if(direction)direction.textContent=lightDirectionLabel(light,preset)+' · light '+Math.round(light.azimuth)+'°/'+Math.round(light.elevation)+'° · subject '+Math.round(preset.subjectYaw)+'°/'+Math.round(preset.subjectPitch)+'°';const anchor=nearestLightAnchor(light);for(const button of $$('.lighting-position-button'))button.classList.toggle('active',button.dataset.position===anchor);for(const dot of $$('.lighting-orbit-dot'))dot.classList.toggle('active',Number(dot.dataset.index)===customLighting.active)}
function renderCustomLightingEditor(){const preset=customLighting.draft;if(!preset)return;customLighting.open=true;customLighting.active=Math.max(0,Math.min(customLighting.active,preset.lights.length-1));const light=preset.lights[customLighting.active];$('#cinema-picker-title').textContent='New lighting preset';$('#cinema-picker-help').textContent='Place up to 3 lights. The controls become functional MiniMax lighting direction.';$('#cinema-picker-custom').hidden=true;$('#cinema-picker-done').textContent='Back';const body=$('#cinema-picker-body');body.innerHTML='<section class="custom-lighting-editor"><div class="custom-lighting-tabs"></div><div class="custom-lighting-workspace"><div class="custom-lighting-controls"><label>Preset name<input id="custom-lighting-name" maxlength="40"></label><label>Light type<select id="custom-light-type"><option>Key light</option><option>Fill light</option><option>Rim light</option><option>Practical light</option><option>Background light</option></select></label><label>Color<div class="lighting-color-row"><input id="custom-light-color" type="color"><input id="custom-light-hex" maxlength="7"></div></label><label>Brightness <b id="custom-light-brightness-value"></b><input id="custom-light-brightness" type="range" min="0" max="100"></label><label>Diffusion <b id="custom-light-diffusion-value"></b><input id="custom-light-diffusion" type="range" min="0" max="100"></label></div><div class="custom-lighting-stage"><div class="lighting-orbit" aria-label="Drag a light around the subject"><div class="lighting-subject" role="button" tabindex="0"><span>SUBJECT</span></div><div class="lighting-orbit-dots"></div></div><small class="lighting-drag-help">Drag a light to orbit it · Drag the subject to rotate its facing</small><output id="custom-light-direction"></output></div><div class="custom-lighting-positions"><b>Quick position</b><div></div></div></div><div class="custom-lighting-actions"><button type="button" data-apply>Apply</button><button type="button" data-save>Save as preset</button></div><p class="custom-lighting-note">Brightness and diffusion are translated into relative cinematic language; final lighting remains generative rather than photometrically exact.</p></section>';const tabs=body.querySelector('.custom-lighting-tabs');preset.lights.forEach((item,index)=>{const button=document.createElement('button');button.type='button';button.classList.toggle('active',index===customLighting.active);button.textContent=item.name;button.onclick=()=>{customLighting.active=index;renderCustomLightingEditor()};tabs.append(button)});if(preset.lights.length<3){const add=document.createElement('button');add.type='button';add.textContent='+ Add Light';add.onclick=()=>{preset.lights.push(defaultCustomLight(preset.lights.length));customLighting.active=preset.lights.length-1;renderCustomLightingEditor()};tabs.append(add)}if(preset.lights.length>1){const remove=document.createElement('button');remove.type='button';remove.className='remove-light';remove.textContent='Remove';remove.onclick=()=>{preset.lights.splice(customLighting.active,1);customLighting.active=Math.max(0,customLighting.active-1);renderCustomLightingEditor()};tabs.append(remove)}ensureSubjectOrbit(preset);const subject=body.querySelector('.lighting-subject');positionLightingSubject(subject,preset);bindLightingSubject(subject,preset);const dots=body.querySelector('.lighting-orbit-dots');preset.lights.forEach((item,index)=>{const beam=document.createElement('span');beam.className='lighting-light-beam';const dot=document.createElement('i');dot.className='lighting-orbit-dot';dot.dataset.index=String(index);dot.dataset.position=item.position;dot.style.setProperty('--light-color',item.color);dot._beam=beam;positionLightDot(dot,item);bindLightDotDrag(dot,item,index);dots.append(beam,dot)});const positions=body.querySelector('.custom-lighting-positions div');for(const position of ['Top','Front','Right','Left','Back','Bottom']){const button=document.createElement('button');button.type='button';button.className='lighting-position-button';button.dataset.position=position;button.textContent=position;button.onclick=()=>{setLightAnchor(light,position);renderCustomLightingEditor()};positions.append(button)}$('#custom-lighting-name').value=preset.name;$('#custom-lighting-name').oninput=event=>preset.name=event.target.value;$('#custom-light-type').value=light.type;$('#custom-light-type').onchange=event=>light.type=event.target.value;$('#custom-light-color').value=light.color;$('#custom-light-hex').value=light.color;const setColor=value=>{if(!/^#[0-9a-f]{6}$/i.test(value))return;light.color=value.toUpperCase();renderCustomLightingEditor()};$('#custom-light-color').oninput=event=>setColor(event.target.value);$('#custom-light-hex').onchange=event=>setColor(event.target.value);$('#custom-light-brightness').value=light.brightness;$('#custom-light-brightness').oninput=event=>{light.brightness=Number(event.target.value);updateCustomLightingLabels()};$('#custom-light-diffusion').value=light.diffusion;$('#custom-light-diffusion').oninput=event=>{light.diffusion=Number(event.target.value);updateCustomLightingLabels()};body.querySelector('[data-apply]').onclick=()=>{setCustomLightingSelection(preset);customLighting.open=false;$('#cinema-picker-dialog').close()};body.querySelector('[data-save]').onclick=()=>{const rows=savedLightingPresets();let id=preset.id;if(!id){id=Date.now().toString(36)+Math.random().toString(36).slice(2,7);preset.id=id}else{const old=rows.findIndex(item=>item.id===id);if(old>=0)rows.splice(old,1)}preset.name=(preset.name||'Custom lighting').trim();rows.push(cloneLighting(preset));saveLightingPresets(rows);setCustomLightingSelection(preset,id);customLighting.open=false;renderLightingPicker()};updateCustomLightingLabels()}

const renderCinemaPickerBase=renderCinemaPicker;
