const cinemaPickerDoneBase=$('#cinema-picker-done').onclick;
$('#cinema-picker-done').onclick=()=>{if(cinemaPickerType==='lighting'&&customLighting.open){customLighting.open=false;renderLightingPicker();return}if(cinemaPickerType==='palette'&&customPalette.open){setCinemaControl('#cinema-palette',customPalettePrompt());customPalette.open=false}$('#cinema-picker-dialog').close()};
$('#cinema-picker-custom').onclick=()=>{if(cinemaPickerType!=='palette')return $('#cinema-save-preset').click();if(!customPalette.open)return renderCustomPaletteEditor();const name=prompt('Palette name');if(!name?.trim())return;const items=savedColorPalettes();items.push({name:name.trim(),colors:[...customPalette.colors],intensity:customPalette.intensity,prompt:customPalettePrompt()});localStorage.setItem(paletteStorageKey(),JSON.stringify(items));setCinemaControl('#cinema-palette',customPalettePrompt());customPalette.open=false;renderPalettePicker()};
let expandedUserAccessV195=null;
loadUsers=async function(){const{users,models=[],resolutions=[]}=await api('/api/admin/users');const list=$('#user-list');list.innerHTML='';const saveAccess=async(user,field,item,enabled,button)=>{button.disabled=true;expandedUserAccessV195=user.id;try{await api(`/api/admin/users/${user.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({[field]:{[item.id]:!enabled}})});await loadUsers();await loadPresets()}catch(error){alert(error.message);button.disabled=false}};const permissionGroup=(user,title,items,field)=>{const allowed=user[field]||[];const group=document.createElement('details');group.className=`permission-group-v195 ${field==='resolution_access'?'resolutions-v196':'models-v196'}`;group.open=true;const summary=document.createElement('summary');summary.innerHTML=`<span>${title}</span><small>${allowed.length}/${items.length} allowed</small>`;const grid=document.createElement('div');grid.className='permission-grid-v195';for(const item of items){const enabled=allowed.includes(item.id);const button=document.createElement('button');button.type='button';button.className=enabled?'enabled':'';button.innerHTML=`<i>${enabled?'✓':'＋'}</i><span><b></b><small>${enabled?'Allowed':'Blocked'}</small></span>`;button.querySelector('b').textContent=item.label;button.onclick=()=>saveAccess(user,field,item,enabled,button);grid.append(button)}group.append(summary,grid);return group};for(const user of users){const card=document.createElement('details');card.className='team-user-card-v195';card.open=expandedUserAccessV195===user.id;card.ontoggle=()=>{if(card.open)expandedUserAccessV195=user.id;else if(expandedUserAccessV195===user.id)expandedUserAccessV195=null};const summary=document.createElement('summary');summary.innerHTML='<span class="team-user-identity-v195"><b></b><small></small></span><span class="team-user-badges-v195"></span><i>⌄</i>';summary.querySelector('b').textContent=user.username;summary.querySelector('small').textContent=user.role==='admin'?'Administrator':'Team member';const badges=summary.querySelector('.team-user-badges-v195');badges.innerHTML=`<em class="${user.enabled?'active':'disabled'}">${user.enabled?'Active':'Disabled'}</em>${user.role==='admin'?'<em>Full access</em>':`<em>${(user.model_access||[]).length} models</em>`}`;const body=document.createElement('div');body.className='team-user-body-v195';const actions=document.createElement('div');actions.className='team-user-actions-v195';const toggle=document.createElement('button');toggle.textContent=user.enabled?'Disable':'Enable';toggle.disabled=user.id===state.user.id;toggle.onclick=async()=>{expandedUserAccessV195=user.id;await api(`/api/admin/users/${user.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:!user.enabled,logout_all:true})});await loadUsers()};const reset=document.createElement('button');reset.textContent='Reset password';reset.onclick=async()=>{const password=prompt(`New password for ${user.username}`);if(!password)return;try{await api(`/api/admin/users/${user.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({password,logout_all:true})});alert('Password reset. Share the new password securely.')}catch(error){alert(error.message)}};const remove=document.createElement('button');remove.className='danger';remove.textContent='Delete user';remove.disabled=user.id===state.user.id||user.role==='admin';remove.onclick=async()=>{if(!confirm(`Delete ${user.username} and all of this user's projects and media? This cannot be undone.`))return;await api(`/api/admin/users/${user.id}`,{method:'DELETE'});expandedUserAccessV195=null;await loadUsers()};actions.append(toggle,reset,remove);body.append(actions);if(user.role==='admin'){const full=document.createElement('div');full.className='admin-full-access-v195';full.innerHTML='<b>✓ Full administrator access</b><small>All models and resolutions are always available. No permission maintenance required.</small>';body.append(full)}else{const permissions=document.createElement('div');permissions.className='team-permissions-v195';permissions.append(permissionGroup(user,'Models',models,'model_access'),permissionGroup(user,'Resolutions',resolutions,'resolution_access'));body.append(permissions)}card.append(summary,body);list.append(card)}};

let mentionGalleryView='uploads';
async function deleteMentionUpload(asset,event){event.stopPropagation();if(!confirm(`Delete ${asset.filename}? This cannot be undone.`))return;try{await api(`/api/assets/${encodeURIComponent(asset.id)}`,{method:'DELETE'});mentionSelection.delete(asset.id);mentionAssets=mentionAssets.filter(item=>item.id!==asset.id);state.galleryAssets=state.galleryAssets.filter(item=>item.id!==asset.id);const holder=[...document.querySelectorAll('#reference-thumbs .reference-thumb')].find(node=>node.dataset.referenceAssetId===String(asset.id));if(holder)holder.click();renderMentionPicker()}catch(error){alert(error.message)}}
function mentionItemCard(asset){const card=document.createElement('div');card.className=`mention-asset${mentionSelection.has(asset.id)?' selected':''}`;card.tabIndex=0;card.setAttribute('role','button');card.title='Click to select · Double-click to add and close';const image=document.createElement('img');image.src=asset.thumbnail_url||asset.url;image.alt=asset.filename;image.loading='lazy';const name=document.createElement('span');name.textContent=asset.filename;const source=document.createElement('small');source.textContent=asset.source==='upload'?'Uploaded':'Generated';source.className=asset.source==='upload'?'uploaded':'generated';const check=document.createElement('b');check.textContent='✓';card.append(image,name,source,check);if(asset.source==='upload'&&asset.can_manage!==false){const remove=document.createElement('button');remove.type='button';remove.className='mention-delete';remove.textContent='🗑';remove.title='Delete uploaded image';remove.setAttribute('aria-label','Delete uploaded image');remove.onclick=event=>deleteMentionUpload(asset,event);card.append(remove)}const select=()=>{if(mentionSelection.has(asset.id))return true;const usedSlots=document.querySelectorAll('#prompt-editor .inline-mention').length+state.references.filter(item=>!item.assetId).length;if(usedSlots+mentionSelection.size>=9){alert('Maximum 9 image-reference occurrences allowed.');return false}mentionSelection.add(asset.id);return true};const update=()=>{card.classList.toggle('selected',mentionSelection.has(asset.id));$('#mention-selection-count').textContent=`${mentionSelection.size} selected`};const toggle=()=>{if(mentionSelection.has(asset.id))mentionSelection.delete(asset.id);else if(!select())return;update()};card.onclick=toggle;card.ondblclick=event=>{event.preventDefault();event.stopPropagation();if(!select())return;update();$('#apply-mentions').click()};card.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();toggle()}};return card}
renderMentionPicker=function(){const uploads=mentionAssets.filter(asset=>asset.source==='upload');const generated=mentionAssets.filter(asset=>asset.source!=='upload');$('#mention-upload-count').textContent=uploads.length;$('#mention-generated-count').textContent=generated.length;$$('[data-mention-view]').forEach(button=>button.classList.toggle('active',button.dataset.mentionView===mentionGalleryView));const shown=mentionGalleryView==='uploads'?uploads:generated;const grid=$('#mention-grid');grid.innerHTML='';if(!shown.length)grid.innerHTML=`<p class="mention-empty">No ${mentionGalleryView} images yet.</p>`;for(const asset of shown)grid.append(mentionItemCard(asset));$('#mention-selection-count').textContent=`${mentionSelection.size} selected`};
$$('[data-mention-view]').forEach(button=>button.onclick=()=>{mentionGalleryView=button.dataset.mentionView;renderMentionPicker()});
async function instantUploadMentionFiles(files,addToReferences=false){if(!state.project)return alert('Select a project first.');const usable=[...files].filter(file=>file.type.startsWith('image/'));for(const file of usable){try{const assetId=await uploadFile(file);const item={id:assetId,assetId,filename:file.name,mime_type:file.type||'image/png',kind:'image',source:'upload',url:`/media/${assetId}`};if(!mentionAssets.some(asset=>asset.id===assetId))mentionAssets.unshift(item);if(addToReferences)appendReference(item,'#reference-thumbs','#reference-count','references',9)}catch(error){alert(`${file.name}: ${error.message}`)}}mentionGalleryView='uploads';renderMentionPicker()}
