/* v146 visible shot-mode directions: preview and compiler share this exact source. */
function cinemaShotModeDirection(){
  const total=Math.max(1,Number($('#duration').value)||5);
  if(cinema.mode==='auto')return `shot mode: Generate ONE coherent ${total.toFixed(1)}-second video as an automatically directed multishot sequence. Decide the appropriate number of editorial shots, shot order, framing, camera angles, camera movement and cut timing from the scene. Use purposeful clean cuts only where they improve storytelling. Preserve the exact same characters, faces, wardrobe, props, location, lighting, spatial geography, action and dialogue continuity across every cut. Do not restart the action after a cut.`;
  if(cinema.mode==='custom')return `shot mode: Generate ONE continuous ${total.toFixed(1)}-second video in ONE generation using ONE model, containing exactly ${Math.max(1,cinema.shots.length)} editorial shot${cinema.shots.length===1?'':'s'} joined by clean intentional camera cuts at the specified timeline timestamps. Preserve the exact same characters, faces, wardrobe, props, location, lighting, spatial geography and ongoing action or dialogue across every cut. Do not restart the action after a cut.`;
  return `shot mode: Create one uninterrupted continuous take for the entire ${total.toFixed(1)}-second video. No editorial cuts, no montage and no transitions.`;
}
presetCinemaDirectionLines=function(){return[cinemaShotModeDirection(),...cinemaDirectionSetPreset({camera:''})]};
cinemaDirectionSet=function(shot={}){
  if(cinema.directionOverride===null||cinema.directionOverride===undefined){
    const lines=[cinemaShotModeDirection(),...cinemaDirectionSetPreset(shot)];
    return lines;
  }
  return cinema.directionOverride.split(/\r?\n/).map(line=>line.trim()).filter(Boolean);
};
compileCinemaPrompt=function(shot){
  const scene=shot.prompt.trim()||$('#prompt').value.trim();
  const directions=cinemaDirectionSet(shot);
  return[scene,directions.length&&`Applied cinema directions:\n${directions.join('\n')}`].filter(Boolean).join('\n\n');
};
compileCinemaAutoMultishotPrompt=function(baseDuration){
  const total=Math.max(1,Number(baseDuration)||5);
  const master=$('#prompt').value.trim();
  const directions=cinemaDirectionSet({camera:''});
  return{prompt:[master&&`Master scene: ${master}`,directions.length&&`Applied cinema directions:\n${directions.join('\n')}`].filter(Boolean).join('\n\n'),duration:total};
};
compileCinemaMultishotPrompt=function(baseDuration){
  const timeline=cinemaTimeline(baseDuration);
  const total=Number(baseDuration)||5;
  const master=$('#prompt').value.trim();
  const segments=timeline.map(({shot,start,end,duration},index)=>{const framing=cinemaCameraInstruction(shot.camera);return `Shot ${index+1} [${start.toFixed(1)}s-${end.toFixed(1)}s, duration ${duration.toFixed(1)}s]: ${shot.prompt.trim()||master||'continue the scene'}${framing?`; camera shot/framing: ${framing}`:''}`});
  const directions=cinemaDirectionSet({camera:''});
  const prompt=[master&&`Master scene: ${master}`,`Timeline and shot list:\n${segments.join('\n')}`,directions.length&&`Applied cinema directions:\n${directions.join('\n')}`].filter(Boolean).join('\n\n');
  return{prompt,duration:total,timeline};
};
