const JOB_LABELS_V148={'minimax-h3-cinema-lab':'Cinema Lab · Research','minimax-h3-cinema-consistency':'Cinema Consistency — PDD8','flux-image':'Flux Image','minimax-h3':'MiniMax H3 — Fast (16 steps)','minimax-h3-faster':'MiniMax H3 — Faster (10 steps)','minimax-h3-superfast':'MiniMax H3 — Superfast (4 steps)','minimax-h3-best':'MiniMax H3 — Best (20 steps)','minimax-h3-teacache':'MiniMax H3 — TeaCache Balanced (20 steps)','minimax-h3-pdd':'MiniMax H3 — PDD Acc (8 steps)','minimax-h3-video-turbo':'MiniMax H3 — Video Turbo HD (8-step + Latent Upscale)','ltx-2.5':'LTX 2.5','realesrgan-video-fast':'Real-ESRGAN Video','seedvr-upscale':'SeedVR2','realesrgan-photo':'Real-ESRGAN Photo','realesrgan-anime':'Real-ESRGAN Anime'};
function jobStatusTextV148(job){
  const progress=Number.isFinite(Number(job.progress))?Number(job.progress):0;
  const totalTime=formatGenerationTime(job.generation_seconds),etaTime=formatGenerationTime(job.eta_seconds);
  const stepText=job.step_current!=null&&job.step_max?` · step ${job.step_current}/${job.step_max}`:'';
  const projectText=job.project_name?`${job.project_name} · `:'';
  if(job.status==='completed')return projectText+(job.cached?'Cached':`Completed${totalTime?` · ${totalTime}`:''}`);
  if(job.status==='failed')return projectText+(job.error==='Cancelled by user'?'Cancelled':'Failed');
  if(job.status==='queued')return projectText+`Queued · ~${formatGenerationTime(job.estimated_total_seconds)}`;
  return projectText+(etaTime?`Estimated ${progress}%${stepText} · ~${etaTime} left`:`${progress}%${stepText} · Finishing…`);
}
