/* v153: compact Video Edit composer and first-frame painted target masks. */
state.editMask=null;
let videoMaskBacking=null,videoMaskPainting=false,videoMaskErase=false,videoMaskLast=null;
function videoEditSourceUrl(){const item=state.sourceMedia;if(!item)return'';if(item instanceof File)return URL.createObjectURL(item);return item.url||''}
function clearVideoMask(){if(!videoMaskBacking)return;const context=videoMaskBacking.getContext('2d');context.fillStyle='#000';context.fillRect(0,0,videoMaskBacking.width,videoMaskBacking.height);const display=$('#video-mask-canvas').getContext('2d');display.clearRect(0,0,display.canvas.width,display.canvas.height);$('#video-mask-status').textContent='Draw the target in red'}
function sizeVideoMask(){const video=$('#video-mask-source'),canvas=$('#video-mask-canvas');if(!video.videoWidth)return;canvas.width=video.videoWidth;canvas.height=video.videoHeight;videoMaskBacking=document.createElement('canvas');videoMaskBacking.width=canvas.width;videoMaskBacking.height=canvas.height;clearVideoMask()}
function openVideoMask(){const url=videoEditSourceUrl();if(!url)return alert('Choose a source video first.');const video=$('#video-mask-source');video.src=url;video.onloadedmetadata=()=>{sizeVideoMask();video.currentTime=0};$('#video-mask-dialog').showModal()}
function maskPoint(event){const canvas=$('#video-mask-canvas'),rect=canvas.getBoundingClientRect();return{x:(event.clientX-rect.left)*canvas.width/rect.width,y:(event.clientY-rect.top)*canvas.height/rect.height}}
function paintMaskLine(from,to){const size=Number($('#video-mask-size').value);const visible=$('#video-mask-canvas').getContext('2d'),mask=videoMaskBacking.getContext('2d');for(const [context,color] of [[visible,videoMaskErase?'rgba(0,0,0,1)':'rgba(255,40,40,.65)'],[mask,videoMaskErase?'#000':'#fff']]){context.save();context.globalCompositeOperation=videoMaskErase&&context===visible?'destination-out':'source-over';context.strokeStyle=color;context.lineWidth=size;context.lineCap='round';context.lineJoin='round';context.beginPath();context.moveTo(from.x,from.y);context.lineTo(to.x,to.y);context.stroke();context.restore()}}
$('#video-edit-draw').onclick=openVideoMask;$('#video-mask-close').onclick=()=>$('#video-mask-dialog').close();
$('#video-mask-brush').onclick=()=>{videoMaskErase=false;$('.video-mask-stage').classList.add('painting');$('#video-mask-brush').classList.add('active');$('#video-mask-erase').classList.remove('active');$('#video-mask-source').pause()};
$('#video-mask-erase').onclick=()=>{videoMaskErase=true;$('.video-mask-stage').classList.add('painting');$('#video-mask-erase').classList.add('active');$('#video-mask-brush').classList.remove('active');$('#video-mask-source').pause()};
