$('#video-mask-canvas').addEventListener('pointerdown',event=>{if(!videoMaskBacking)return;videoMaskPainting=true;videoMaskLast=maskPoint(event);event.currentTarget.setPointerCapture(event.pointerId);paintMaskLine(videoMaskLast,videoMaskLast)});
$('#video-mask-canvas').addEventListener('pointermove',event=>{if(!videoMaskPainting)return;const point=maskPoint(event);paintMaskLine(videoMaskLast,point);videoMaskLast=point});
for(const type of ['pointerup','pointercancel'])$('#video-mask-canvas').addEventListener(type,()=>{videoMaskPainting=false;videoMaskLast=null});
$('#video-mask-apply').onclick=()=>{if(!videoMaskBacking)return;videoMaskBacking.toBlob(blob=>{state.editMask=new File([blob],'painted-target-mask.png',{type:'image/png'});$('#video-edit-target').value=$('#video-edit-target').value.trim()||'the manually painted target';$('#video-edit-draw').textContent='✓ Target painted';$('#video-mask-status').textContent='Painted mask ready';$('#video-mask-dialog').close()},'image/png')};
