/* v166: upload images immediately and refresh the canonical Uploads gallery. */
const instantUploadMentionFilesV166=instantUploadMentionFiles;
instantUploadMentionFiles=async function(files,addToReferences=false){
  await instantUploadMentionFilesV166(files,addToReferences);
  if(!state.project)return;
  try{
    const {assets}=await api(`/api/gallery?project_id=${encodeURIComponent(state.project.id)}&upload_refresh=${Date.now()}`);
    state.galleryAssets=assets;
    mentionAssets=assets.filter(asset=>asset.kind==='image');
  }catch(error){console.warn('Upload gallery refresh unavailable',error)}
  mentionGalleryView='uploads';
  renderMentionPicker();
};
$('#quick-upload-input').onchange=async event=>{
  const input=event.target,files=[...input.files];
  input.disabled=true;
  const extType=file=>{
    if(file.type.startsWith('image/'))return'image';
    if(file.type.startsWith('video/'))return'video';
    if(file.type.startsWith('audio/'))return'audio';
    const ext=file.name.split('.').pop().toLowerCase();
    if(['jpg','jpeg','png','webp','gif','bmp','avif'].includes(ext))return'image';
    if(['mp4','mov','mkv','webm','avi','m4v'].includes(ext))return'video';
    if(['mp3','wav','flac','m4a','aac','ogg'].includes(ext))return'audio';
    return'';
  };
  const images=files.filter(file=>extType(file)==='image');
  if(images.length)await instantUploadMentionFiles(images,true);
  for(const file of files.filter(file=>extType(file)!=='image')){
    const kind=extType(file);
    if(kind==='video')appendReference(file,'#video-reference-thumbs','#video-reference-count','videoRefs',2);
    else if(kind==='audio')appendReference(file,'#audio-reference-thumbs','#audio-reference-count','audioRefs',2);
    else alert(`${file.name}: Unsupported file type`);
  }
  input.value='';input.disabled=false;
};

