/* v175: keep Audio dialogue/transcript state isolated from Image, Video, Edit and Cinema. */
const audioModeDraftsV175={};
let audioPreviousModeV175=$('.mode.active')?.dataset.mode||'image';
let audioDraftVisitedV175=false;
audioModeDraftsV175[audioPreviousModeV175]=$('#prompt-editor')?.innerHTML||'';
const syncModeBeforeAudioIsolationV175=syncMode;
syncMode=function(){
  const nextMode=$('.mode.active')?.dataset.mode||'image';
  const editor=$('#prompt-editor');
  const transcript=$('#tts-reference-text');
  if(editor&&nextMode!==audioPreviousModeV175){
    if(audioPreviousModeV175==='tts'){
      audioModeDraftsV175.tts=editor.innerText||'';
      audioModeDraftsV175.ttsTranscript=transcript?.value||'';
    }else{
      audioModeDraftsV175[audioPreviousModeV175]=editor.innerHTML;
    }
    if(nextMode==='tts'){
      editor.textContent=audioDraftVisitedV175?(audioModeDraftsV175.tts||''):'';
      if(transcript)transcript.value=audioDraftVisitedV175?(audioModeDraftsV175.ttsTranscript||''):'';
      audioDraftVisitedV175=true;
    }else{
      editor.innerHTML=audioModeDraftsV175[nextMode]||'';
    }
    audioPreviousModeV175=nextMode;
    syncPromptValue();
  }
  return syncModeBeforeAudioIsolationV175();
};



