/* v180: image swap can start from either an inline @Image token or its selected-media preview chip. */
function openImageMentionSwapV180(token){
  if(!token||!token.isConnected)return;
  mentionSwapTokenV178=token;characterSwapTokenV179=null;mentionSelection.clear();captureMentionRange(false);openMentionPicker();
}
const renderPromptMentionStripBeforeV180=renderPromptMentionStrip;
renderPromptMentionStrip=function(){
  renderPromptMentionStripBeforeV180();
  const uniqueTokens=[],seen=new Set();
  for(const token of $$('#prompt-editor .inline-character-mention, #prompt-editor .inline-mention')){
    const isCharacter=token.classList.contains('inline-character-mention');
    const key=(isCharacter?'character:':'image:')+(isCharacter?token.dataset.characterId:token.dataset.assetId);
    if(seen.has(key))continue;seen.add(key);uniqueTokens.push(token);
  }
  const chips=$$('#prompt-mention-strip .prompt-mention-preview');
  chips.forEach((chip,index)=>{
    const token=uniqueTokens[index];if(!token)return;
    chip.tabIndex=0;chip.setAttribute('role','button');chip.classList.add('mention-swap-trigger');
    chip.title=token.classList.contains('inline-mention')?'Click to replace this image mention':'Click to replace this character, element or prop mention';
    const activate=()=>{
      if(token.classList.contains('inline-mention'))openImageMentionSwapV180(token);
      else{characterSwapTokenV179=token;mentionSwapTokenV178=null;mentionSelection.clear();captureMentionRange(false);openMentionPicker()}
    };
    chip.onclick=activate;chip.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();activate()}};
  });
};
